import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"审查域 J 报告：API 接口全量审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/J-api.md","filePath":"audit/J-api.md","lastUpdated":1792448513000}'),i={name:"audit/J-api.md"};function c(n,e,r,l,u,s){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="审查域-j-报告-api-接口全量审计" tabindex="-1">审查域 J 报告：API 接口全量审计 <a class="header-anchor" href="#审查域-j-报告-api-接口全量审计" aria-label="Permalink to &quot;审查域 J 报告：API 接口全量审计&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：<code>go-backend/internal/http/handler/handler.go</code> 注册的全部 187 个路由</li><li>鉴权模型：<code>middleware/auth.go</code> 的 JWT 中间件（<code>shouldSkip</code>/<code>requiresAdmin</code>）</li><li>发现问题数：<strong>P0 0 / P1 1 / P2 3 / P3 5</strong></li><li>实际执行的验证：路由表全量导出分类、6 个新增移植路由逐行审查、开放接口滥用面分析、鉴权回归测试运行</li></ul><h2 id="鉴权模型-基线确认" tabindex="-1">鉴权模型（基线确认） <a class="header-anchor" href="#鉴权模型-基线确认" aria-label="Permalink to &quot;鉴权模型（基线确认）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>完全开放（无鉴权）</td><td><code>/flow/*</code></td><td>节点 agent 上报，用 <code>secret</code> 查询参数鉴权</td></tr><tr><td>完全开放</td><td><code>/api/v1/open_api/*</code></td><td>订阅/ GitHub 镜像，token 或 HMAC 鉴权</td></tr><tr><td>完全开放</td><td><code>/api/v1/captcha/*</code>、<code>/api/v1/user/login</code>、passkey 登录、<code>public/config/get</code></td><td>登录前必需</td></tr><tr><td>完全开放</td><td><code>/api/v1/federation/connect</code>、<code>/api/v1/federation/tunnel/create</code>、<code>/api/v1/federation/runtime/*</code></td><td>联邦对等，用 <code>authPeer</code> 包装器鉴权</td></tr><tr><td>仅管理员</td><td><code>/api/v1/node/*</code>、<code>/api/v1/kernel/*</code>、<code>/api/v1/inbound/*</code>（除 <code>sub/info</code>）、<code>/api/v1/subscription/*</code>、<code>/api/v1/system/*</code>、<code>/api/v1/backup/*</code>、<code>/api/v1/tunnel/*</code>（除 user 子路径）、<code>/api/v1/speed-limit/*</code>、<code>/api/v1/group/*</code>、<code>/api/v1/federation/share/*</code>、<code>/api/v1/monitor/permission/*</code></td><td><code>requiresAdmin</code> 按路径前缀判定</td></tr><tr><td>登录用户</td><td>其余（<code>user-inbound/mine</code>、<code>tunnel/user/*</code>、<code>monitor/*</code> 非 permission 路径等）</td><td>handler 内二次鉴权</td></tr></tbody></table><p><code>requiresAdmin</code> 采用前缀匹配而非精确路由表——新增路由只要落在上述前缀下自动受保护。6 个新增移植路由中 5 个落在 <code>/api/v1/node/*</code> 下（自动 admin），1 个（gh_mirror）落在 <code>/api/v1/open_api/</code> 下（故意开放）。</p><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><h3 id="j-001-api-v1-user-inbound-list-与-api-v1-user-inbound-set-依赖-handler-内鉴权而非中间件" tabindex="-1">J-001 <code>/api/v1/user-inbound/list</code> 与 <code>/api/v1/user-inbound/set</code> 依赖 handler 内鉴权而非中间件 <a class="header-anchor" href="#j-001-api-v1-user-inbound-list-与-api-v1-user-inbound-set-依赖-handler-内鉴权而非中间件" aria-label="Permalink to &quot;J-001 `/api/v1/user-inbound/list` 与 `/api/v1/user-inbound/set` 依赖 handler 内鉴权而非中间件&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/middleware/auth.go:149-230</code>（<code>requiresAdmin</code> 未覆盖 <code>/api/v1/user-inbound/</code> 前缀）；<code>go-backend/internal/http/handler/user_inbound.go:35-71</code></li><li>现象：<code>getUserInbounds</code>（返回<strong>任意用户</strong>的全部订阅分配）和 <code>setUserInbounds</code>（修改任意用户分配）这两个高敏接口，在中间件层被视为&quot;普通登录用户可访问&quot;，仅靠 handler 内的 <code>userRoleFromRequest</code> + <code>roleID != 0</code> 检查挡住。</li><li>风险：纵深防御缺失——一旦某次重构误删 handler 内检查（或新增同类接口时忘记加），即变为任意登录用户可读写全站订阅分配的 IDOR/越权。<code>requiresAdmin</code> 的前缀表是主要防线，此处开了缺口。</li><li>修复方向：在 <code>requiresAdmin</code> 中加入 <code>strings.HasPrefix(path, &quot;/api/v1/user-inbound/&quot;)</code> 且 <code>path != &quot;/api/v1/user-inbound/mine&quot;</code>，与 handler 内检查形成双层防护。</li></ul><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="j-002-github-镜像开放代理可被滥用于带宽-磁盘消耗" tabindex="-1">J-002 GitHub 镜像开放代理可被滥用于带宽/磁盘消耗 <a class="header-anchor" href="#j-002-github-镜像开放代理可被滥用于带宽-磁盘消耗" aria-label="Permalink to &quot;J-002 GitHub 镜像开放代理可被滥用于带宽/磁盘消耗&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/gh_mirror.go:172</code>（<code>githubMirror</code>）；<code>middleware/auth.go:118</code>（<code>shouldSkip</code> 覆盖 <code>/api/v1/open_api/</code>）</li><li>现象：<code>/api/v1/open_api/gh/</code> 无需任何鉴权。虽有 10 仓库白名单、单文件 300MB、总缓存 2GB、单航班去重，但攻击者仍可遍历白名单仓库的大文件（如反复请求不同 tag 的内核二进制）打满 2GB 缓存、消耗面板出站带宽。<code>ghMirrorLatestTag</code> 的 HEAD 请求也可被触发。</li><li>风险：中。属设计权衡（国内节点需经面板拉内核），但无任何限流。</li><li>修复方向：对该路径加独立 IP 限流（如每 IP 每分钟 20 次），或要求节点 secret 查询参数。</li></ul><h3 id="j-003-nodelatencyprobe-空-ids-探测全部节点无二次确认" tabindex="-1">J-003 <code>nodeLatencyProbe</code> 空 IDs 探测全部节点无二次确认 <a class="header-anchor" href="#j-003-nodelatencyprobe-空-ids-探测全部节点无二次确认" aria-label="Permalink to &quot;J-003 `nodeLatencyProbe` 空 IDs 探测全部节点无二次确认&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/node_latency.go:512-537</code></li><li>现象：<code>ids</code> 为空时探测<strong>全部</strong>节点（注释明示 &quot;all of them when empty&quot;）。每节点 16 并发 × 每点 4 次 ping，百节点下是显著的出站流量与耗时。admin 误点即触发，无确认。</li><li>修复方向：空 IDs 时拒绝并要求显式传参，或前端加二次确认。</li></ul><h3 id="j-004-nodelatencytargetsset-的-ids-长度无上限" tabindex="-1">J-004 <code>nodeLatencyTargetsSet</code> 的 <code>ids</code> 长度无上限 <a class="header-anchor" href="#j-004-nodelatencytargetsset-的-ids-长度无上限" aria-label="Permalink to &quot;J-004 `nodeLatencyTargetsSet` 的 `ids` 长度无上限&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/node_latency.go:436-510</code></li><li>现象：<code>req.IDs</code> 数组长度不受限（body 上限 10MB），<code>SetNodesLatencyTargets</code> 逐 ID 更新，大数组可造成慢查询。admin-only，风险低。</li><li>修复方向：限制 <code>len(req.IDs) &lt;= 1000</code>。</li></ul><h2 id="p3-体验-备注" tabindex="-1">P3 体验/备注 <a class="header-anchor" href="#p3-体验-备注" aria-label="Permalink to &quot;P3 体验/备注&quot;">​</a></h2><h3 id="j-005-nodetune-的-groups-参数名未经白名单校验-agent-侧已兜底" tabindex="-1">J-005 <code>nodeTune</code> 的 <code>groups</code> 参数名未经白名单校验（agent 侧已兜底） <a class="header-anchor" href="#j-005-nodetune-的-groups-参数名未经白名单校验-agent-侧已兜底" aria-label="Permalink to &quot;J-005 `nodeTune` 的 `groups` 参数名未经白名单校验（agent 侧已兜底）&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/node_tune.go:33-44</code></li><li>现象：<code>groups</code> 任意字符串透传给 agent。agent 侧 <code>applyTuning</code>（<code>go-gost/x/socket/tuning.go:211</code>）对未知 ID 返回&quot;未知调优项&quot;错误，面板侧将其包装为&quot;调优失败&quot;返回。无安全风险，但错误信息可更友好。</li><li>状态：agent 侧已有校验，无需修复，仅记录。</li></ul><h3 id="j-006-flow-的节点-secret-走-url-查询参数" tabindex="-1">J-006 <code>/flow/*</code> 的节点 secret 走 URL 查询参数 <a class="header-anchor" href="#j-006-flow-的节点-secret-走-url-查询参数" aria-label="Permalink to &quot;J-006 `/flow/*` 的节点 secret 走 URL 查询参数&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/handler.go:1021-1038</code></li><li>现象：<code>secret</code> 在 query string 中，会进访问日志、代理日志。属既有设计（agent 上报），不建议改，仅记录。</li></ul><h3 id="j-007-联邦-runtime-command-开放路径依赖-authpeer" tabindex="-1">J-007 联邦 <code>runtime/command</code> 开放路径依赖 <code>authPeer</code> <a class="header-anchor" href="#j-007-联邦-runtime-command-开放路径依赖-authpeer" aria-label="Permalink to &quot;J-007 联邦 `runtime/command` 开放路径依赖 `authPeer`&quot;">​</a></h3><ul><li>文件：<code>middleware/auth.go:126-133</code>（<code>shouldSkip</code> 放行 <code>/api/v1/federation/runtime/*</code>）；<code>handler.go:350</code>（<code>h.authPeer(...)</code> 包装）</li><li>现象：中间件放行后由 <code>authPeer</code> 做对等鉴权。双层结构正确，但 <code>shouldSkip</code> 的放行注释不足，新人易误以为无鉴权。</li><li>状态：实现正确，仅建议补注释，无需修复。</li></ul><h3 id="j-008-备份导入错误码混用-500-2" tabindex="-1">J-008 备份导入错误码混用 500/-2 <a class="header-anchor" href="#j-008-备份导入错误码混用-500-2" aria-label="Permalink to &quot;J-008 备份导入错误码混用 500/-2&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/handler.go:1757-1790</code></li><li>现象：参数错误返回 <code>Err(500)</code>，业务失败返回 <code>Err(-2)</code>，同一接口混用两种错误码体系。前端若只处理一种会漏提示。</li><li>修复方向：统一为业务错误码（低优先级）。</li></ul><h3 id="j-009-openapisubstore-的-get-凭据兼容窗口" tabindex="-1">J-009 <code>openAPISubStore</code> 的 GET 凭据兼容窗口 <a class="header-anchor" href="#j-009-openapisubstore-的-get-凭据兼容窗口" aria-label="Permalink to &quot;J-009 `openAPISubStore` 的 GET 凭据兼容窗口&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/handler.go:699-760</code></li><li>现象：用户名密码仍可走 GET query（已标记 <code>Deprecation: true</code> + <code>Sunset</code>），凭据进 URL 日志。有独立 IP+用户名限流。属过渡期设计，窗口结束后删除即可。</li><li>状态：已知过渡设计，无需修复，仅记录。</li></ul><h2 id="已验证通过" tabindex="-1">已验证通过 <a class="header-anchor" href="#已验证通过" aria-label="Permalink to &quot;已验证通过&quot;">​</a></h2><ol><li><strong>6 个新增移植路由鉴权正确</strong>： <ul><li><code>POST /api/v1/node/latency/probe</code>、<code>POST /api/v1/node/latency/targets</code>（<code>node_latency.go:436,512</code>）：admin-only（<code>/api/v1/node/</code> 前缀），方法/参数校验完整，<code>decodeJSON</code> 10MB 上限 + <code>DisallowUnknownFields</code>。</li><li><code>POST /api/v1/node/tune</code>（<code>node_tune.go:18</code>）：admin-only，action 白名单（<code>&quot;&quot;</code>/<code>status</code>/<code>apply</code>/<code>restore</code>），<code>apply</code> 要求非空 groups，旧 agent 错误被翻译为中文提示。</li><li><code>POST /api/v1/node/route</code>、<code>POST /api/v1/node/route/probe</code>（<code>node_route.go:340,345</code>）：admin-only，<code>id &gt; 0</code> 校验，无 pool 时拒绝 probe。</li><li><code>GET /api/v1/open_api/gh/</code>（<code>gh_mirror.go:172</code>）：故意开放；路径穿越被 <code>ghMirrorSegment</code> 正则 + <code>..</code> 拒绝；重定向被 <code>ghMirrorCheckRedirect</code> 限制在 github.com / *.githubusercontent.com（R5R26-001）；单文件 300MB 在 header 与 body 双重 enforcement；缓存原子写入（tmp + rename）；2GB prune。</li></ul></li><li><strong>订阅开放端点</strong>：<code>/api/v1/open_api/sub/</code> 的 <code>?user=</code>/<code>sig</code> 经 <code>verifySubURLSig</code> 恒定时间比较（<code>user_inbound.go:28-33</code>），无 sig 篡改即 403。</li><li><strong>监控端点</strong>：<code>ensureMonitoringAccess</code>（<code>monitoring.go:872</code>）对非 admin 校验 <code>HasMonitorPermission</code>，未越权。</li><li><strong>登录限流</strong>：<code>M-04</code> 的登录限流与 <code>subStoreLimiter</code> 独立桶均在位。</li><li><strong>备份导入 100MB 上限</strong>（<code>handler.go:1765</code>，R5R22-001）在位。</li></ol><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li>实际 HTTP 发请求验证各接口返回码（无运行中的面板实例；代码审查+回归测试替代）</li><li>联邦对等鉴权 <code>authPeer</code> 的密钥轮换路径（需双面板环境）</li></ul>',31)])])}const g=o(i,[["render",c]]);export{p as __pageData,g as default};
